index.expression:
v.index = v.index + 1;
v.x_pos = math.random(-1,1) * 0.2;
v.y_pos = v.index * 0.2;
v.z_pos = math.random(-1,1) * 0.2;
variable.directionX = v.x_pos_last - v.x_pos;
variable.directionY = v.y_pos_last - v.y_pos;
variable.directionZ = v.z_pos_last - v.z_pos;
v.x_pos_last = v.x_pos;
v.y_pos_last = v.y_pos;
v.z_pos_last = v.z_pos;
t.pos_x = v.x_pos;
t.pos_y = v.y_pos;
t.pos_z = v.z_pos;
t.direction_x = variable.directionX;
t.direction_y = variable.directionY;
t.direction_z = variable.directionZ;

particle_effect.pre_effect_expression:
v.x_pos = t.pos_x;
v.y_pos = t.pos_y;
v.z_pos = t.pos_z;
variable.directionX = t.direction_x;
variable.directionY = t.direction_y;
variable.directionZ = t.direction_Z;
